def build_system_prompt(tools: list) -> str:
    """Генерирует system prompt с описанием инструментов и формата XML."""
    tools_text = format_tools_for_prompt(tools)
    tool_spec = build_tool_format_spec()

    prompt = f"""Ты — AI-ассистент, работающий через OpenCode. Ты ОБЯЗАН генерировать вызовы инструментов через tool calls в формате XML (открывающие и закрывающие угловые скобки тегов tool_calls, invoke, parameter; см. ниже), когда это необходимо.

## Доступные инструменты:
{tools_text}

{tool_spec}

## Важные правила:
1. ВСЕГДА используй XML формат (теги tool_calls, invoke, parameter) для вызова инструментов. Не используй DSML-теги и не пиши JSON-вызовы текстом.
2. Для инструментов с параметрами — ВСЕГДА передавай все обязательные параметры.
3. Если параметр — объект/массив, клади его как JSON внутрь parameter.
4. Числа и boolean — без кавычек (thoughtNumber: 1, nextThoughtNeeded: true).
5. Несколько инструментов — несколько invoke в одном блоке tool_calls.
6. Не генерируй tool_calls если пользователь просто здоровается или задаёт простой вопрос без необходимости в инструментах.
7. Отвечай на русском языке, если не попросят иное."""

    return prompt


@app.post("/v1/chat/completions")
async def proxy(request: Request):
    client_data = await request.json()
    payload = {
        "messages": client_data["messages"],
        "model": "deepseek/deepseek-v4.1-flash",
        "temperature": 0.7,
        "stream": client_data.get("stream", True),  # Пробрасывать stream от клиента
    }
    payload["tools"] = client_data.get("tools")

    # Построить system prompt с инструментами
    sys_prompt = build_system_prompt(client_data.get("tools"))[:20_000]

    # Добавить/заменить system message (первый user-месседж ОСТАЁТСЯ в списке)
    if payload["messages"] and payload["messages"][0]["role"] == "system":
        payload["messages"][0]["content"] = sys_prompt
    else:
        payload["messages"].insert(0, {"role": "system", "content": sys_prompt})

    print(json.dumps(payload, indent=4, ensure_ascii=False))
    # print("promp_length:", len(payload["messages"][0]["content"]))

    resp = session.post(TARGET_URL, json=payload, stream=True)

    if resp.status_code != 200:
        return Response(content=resp.text, status_code=resp.status_code)

    if payload.get("stream", True):
        stop_flag = threading.Event()

        async def check_disconnect():
            while not stop_flag.is_set():
                if await request.is_disconnected():
                    stop_flag.set()
                    break
                await asyncio.sleep(0.5)

        # Запускаем задачу проверки
        asyncio.create_task(check_disconnect())

        def stream_generator():
            for line in resp.iter_lines(decode_unicode=False):
                if line:
                    line = line.decode()
                    if line.strip() == "data: [DONE]":
                        yield line + "\n\n"
                        break
                    # Извлечение usage из SSE
                    if line.startswith("data: "):
                        # Фильтрация <think> тегов
                        line = strip_think_from_sse_line(line)
                    yield line + "\n\n"

        return StreamingResponse(
            stream_generator(),
            status_code=resp.status_code,
            media_type="text/event-stream",
        )
    else:
        # Если стриминг выключен – возвращаем обычный JSON, но преобразуем
        raw_response = resp.text
        data = None
        try:
            data = json.loads(raw_response)
        except json.JSONDecodeError:
            pass

        if data and "choices" in data and data["choices"]:
            message = data["choices"][0].get("message", {})
            if "tool_calls" in message:
                # Уже в нужном формате, просто возвращаем
                return Response(content=raw_response, status_code=resp.status_code)
            # Иначе, возможно, модель вернула текст с вызовом в виде тегов
            content = message.get("content", "")
            content = strip_think_tags(content)
            message["content"] = content
            # Попробуем найти JSON внутри текста (например, {"tool_calls": ...})
            match = re.search(r'(\{"tool_calls":\s*\[.*?\])', content, re.DOTALL)
            if match:
                tool_call_json = match.group(1)
                # Заменяем content на этот JSON и добавляем tool_calls в message
                new_message = message.copy()
                new_message["content"] = None  # или убираем
                new_message["tool_calls"] = json.loads(tool_call_json)["tool_calls"]
                data["choices"][0]["message"] = new_message
                return Response(content=json.dumps(data), status_code=resp.status_code)
        # Если ничего не нашли, возвращаем как есть
        return Response(content=raw_response, status_code=resp.status_code)
